const body = $input.first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return [{ json: { valid: false, errors: ['body must be a JSON object'] } }];
}
const clean = (v) => (typeof v === 'string' ? v : '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim();
const name = clean(body.name).replace(/\s+/g, ' ');
const email = clean(body.email).toLowerCase();
const phoneRaw = clean(body.phone);
const message = clean(body.message);
const source = clean(body.source);
const errors = [];
if (!name || name.length > 200) errors.push('name is required (1-200 characters)');
if (email.length > 254 || !/^[^\s@,;<>"']+@[^\s@,;<>"']+\.[^\s@,;<>"']{2,}$/.test(email)) errors.push('email is missing or not a valid address');
let phone = '';
if (phoneRaw) {
  phone = phoneRaw.replace(/[\s().-]/g, '');
  if (!/^\+?[0-9]{7,15}$/.test(phone)) errors.push('phone must be 7-15 digits, optionally starting with +');
}
if (!message || message.length > 5000) errors.push('message is required (1-5000 characters)');
if (!/^[A-Za-z0-9_-]{1,40}$/.test(source)) errors.push('source is required (letters, digits, - or _, max 40 characters)');
if (errors.length) return [{ json: { valid: false, errors } }];
return [{ json: { valid: true, lead: { name, email, phone, message, source } } }];

