const texts = $input.all().map((i) => String(i.json.data ?? ''));
let schema = null;
let prompt = null;
for (const t of texts) {
  if (schema === null && t.trimStart().startsWith('{')) {
    try { const p = JSON.parse(t); if (p && p.properties) { schema = p; continue; } } catch (e) { /* not the schema */ }
  }
  if (prompt === null) prompt = t;
}
if (!schema || !prompt) throw new Error('Could not load the qualify prompt and schema from /data/prompts');
if (!$env.CLAUDE_MODEL) throw new Error('CLAUDE_MODEL is not set');

const lead = $('Validate & Normalise').first().json.lead;
const lead_id = $('Insert lead (idempotent)').first().json.lead_id;
const strip = (s) => String(s).replace(/<\/?lead>/gi, '');
const userText = `<lead>\nSource: ${strip(lead.source)}\nName: ${strip(lead.name)}\nEmail: ${strip(lead.email)}\nPhone: ${strip(lead.phone) || '(not provided)'}\nMessage:\n${strip(lead.message)}\n</lead>`;

return [{ json: {
  lead_id, lead, schema,
  model: $env.CLAUDE_MODEL,
  prompt_version: $env.QUALIFY_PROMPT_VERSION || 'v1',
  attempt: 1,
  request: { model: $env.CLAUDE_MODEL, max_tokens: 2048, system: prompt, messages: [{ role: 'user', content: userText }] },
} }];

const res = $input.first().json;
const schema = $('Prepare Claude request').first().json.schema;
const ATTEMPT = 1;

function check(s, v) {
  const errs = [];
  if (s.type === 'object') {
    if (v === null || typeof v !== 'object' || Array.isArray(v)) return ['response must be a JSON object'];
    for (const k of s.required || []) if (!(k in v)) errs.push(`missing required key "${k}"`);
    if (s.additionalProperties === false) for (const k of Object.keys(v)) if (!(k in s.properties)) errs.push(`unexpected key "${k}"`);
    for (const [k, sub] of Object.entries(s.properties || {})) if (k in v) errs.push(...check(sub, v[k]).map((e) => `${k}: ${e}`));
  } else if (s.type === 'string') {
    if (typeof v !== 'string') return ['must be a string'];
    if (s.enum && !s.enum.includes(v)) errs.push(`must be one of ${s.enum.join('|')}`);
    if (s.minLength !== undefined && v.length < s.minLength) errs.push(`must be at least ${s.minLength} characters`);
    if (s.maxLength !== undefined && v.length > s.maxLength) errs.push(`must be at most ${s.maxLength} characters`);
  }
  return errs;
}

const fail = (errors, raw = '') => [{ json: { ok: false, attempt: ATTEMPT, errors, raw: String(raw).slice(0, 2000) } }];

if (res.error || res.type === 'error') {
  const e = res.error;
  const msg = typeof e === 'string' ? e : (e && (e.message || e.type)) || 'unknown API error';
  return fail([`Claude API error: ${msg}`]);
}
const blocks = Array.isArray(res.content) ? res.content : [];
const text = blocks.filter((b) => b && b.type === 'text').map((b) => b.text).join('').trim();
if (!text) return fail(['empty response (no text content)']);

let candidate = text;
const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fenced) candidate = fenced[1].trim();
else if (!candidate.startsWith('{')) {
  const a = candidate.indexOf('{'); const b = candidate.lastIndexOf('}');
  if (a !== -1 && b > a) candidate = candidate.slice(a, b + 1);
}
let parsed;
try { parsed = JSON.parse(candidate); } catch (e) { return fail(['response is not valid JSON'], text); }
const errors = check(schema, parsed);
if (errors.length) return fail(errors, text);
return [{ json: { ok: true, attempt: ATTEMPT, result: parsed, errors: [] } }];

const base = $('Prepare Claude request').first().json;
const prev = $input.first().json;
const request = JSON.parse(JSON.stringify(base.request));
if (prev.raw) {
  request.messages.push(
    { role: 'assistant', content: String(prev.raw).trim() },
    { role: 'user', content: `That reply was not valid: ${prev.errors.join('; ')}. Reply again with ONLY the JSON object, using exactly the required keys.` },
  );
}
return [{ json: { ...base, request, attempt: 2 } }];

